# graph dist in 6 domain from all 6 cells adjacent to seed color
from collections import deque
def geodist(grid, target, sources):
    H,W=grid.shape; d=np.full((H,W),9999,int); q=deque()
    for r,c in np.argwhere(grid==target):
        if any(0<=r+dr<H and 0<=c+dc<W and grid[r+dr,c+dc] in sources for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]): d[r,c]=0;q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
            rr,cc=r+dr,c+dc
            if 0<=rr<H and 0<=cc<W and grid[rr,cc]==target and d[rr,cc]>d[r,c]+1: d[rr,cc]=d[r,c]+1;q.append((rr,cc))
    return d
